package org.marketreview.nativeapp;
import org.json.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
public final class ArchiveVideoReviewChecks {
 private static void require(boolean b){if(!b)throw new AssertionError();}
 public static void main(String[]args)throws Exception {File root=Files.createTempDirectory("archived-video-fixture").toFile();File fixture=new File(root,"fixture.media");try{byte[] bytes="test-only bytes".getBytes("UTF-8");Files.write(fixture.toPath(),bytes);StringBuilder sha=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(bytes))sha.append(String.format("%02x",x&255));JSONObject row=new JSONObject().put("id","fixture").put("text","edited").put("assetPath",fixture.getPath()).put("archive",new JSONObject().put("assetPath",fixture.getPath()).put("bytes",bytes.length).put("sha256",sha.toString()));List<File>roots=Arrays.asList(root);String before=ArchiveVideoReviewModel.canonical(row);require(ArchiveVideoReviewModel.inspect(row,row,roots).optBoolean("playable"));JSONObject changed=new JSONObject(row.toString()).put("text","replacement");require(!ArchiveVideoReviewModel.inspect(row,changed,roots).optBoolean("playable"));require(!ArchiveVideoReviewModel.inspect(row,row,Collections.emptyList()).optBoolean("playable"));JSONObject missing=new JSONObject(row.toString());missing.remove("archive");require(!ArchiveVideoReviewModel.inspect(missing,missing,roots).optBoolean("playable"));JSONObject bad=new JSONObject(row.toString());bad.getJSONObject("archive").put("sha256",String.join("",Collections.nCopies(64,"0")));require(!ArchiveVideoReviewModel.inspect(bad,bad,roots).optBoolean("playable"));require(ArchiveVideoReviewModel.seekSeconds(new JSONObject().put("start",1).put("end",2),10)==1);require(ArchiveVideoReviewModel.seekSeconds(new JSONObject().put("start",-1).put("end",2),10)<0);require(ArchiveVideoReviewModel.seekSeconds(new JSONObject().put("start",8).put("end",12),10)<0);require(ArchiveVideoReviewModel.seekSeconds(new JSONObject().put("text","missing"),10)<0);require(before.equals(ArchiveVideoReviewModel.canonical(row)));System.out.println("ArchiveVideoReview JVM guard checks PASS; fixture bytes, no codec acceptance");}finally{Files.deleteIfExists(fixture.toPath());Files.deleteIfExists(root.toPath());}}
 static android.widget.Button button(android.view.View v,String label){if(v instanceof android.widget.Button&&label.equals(((android.widget.Button)v).getText().toString()))return (android.widget.Button)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++){android.widget.Button found=button(group.getChildAt(i),label);if(found!=null)return found;}}return null;}
 static void run(FlowInstrumentation f)throws Exception {JSONObject row=new JSONObject().put("id","read-only-ui-fixture").put("text","edited text").put("originalText","original text");JSONArray segments=new JSONArray();for(int i=0;i<45;i++)segments.put(new JSONObject().put("start",i).put("end",i+1).put("text","segment "+i));row.put("asrResult",new JSONObject().put("text","ASR source").put("segments",segments));f.ui(()->{ArchiveVideoReviewScreen page=new ArchiveVideoReviewScreen(f.activity,row,Collections.singletonList(new File(f.activity.getFilesDir(),"recognition/media")),id->row);require(!button(page,"播放").isEnabled());button(page,"下一页逐字稿").performClick();require(page.saveState().optInt("segmentPage")==1);page.setActive(false);page.restoreState(page.saveState());require(page.saveState().optBoolean("paused")&&page.saveState().optInt("segmentPage")==1);button(page,"核验并打开归档").performClick();page.close();require(!button(page,"播放").isEnabled());});}
}

